(()=>{"use strict";const POLL_MS=5e3;const MAX_MS=6e4;document.addEventListener("submit",e=>{const form=e.target;if(!(form instanceof HTMLFormElement)){return}const question=form.dataset.aaConfirm;if(question&&!confirm(question)){e.preventDefault();form.classList.remove("aa-updating");return}form.classList.add("aa-updating")});document.addEventListener("click",e=>{const link=e.target instanceof Element?e.target.closest("a[data-aa-open]"):null;let box=null;try{box=link?document.getElementById(decodeURIComponent(link.hash.slice(1))):null}catch{}for(let d=box?.closest("details");d;d=d.parentElement?.closest("details")){d.open=true}});const keepState=(old,fresh)=>{fresh.open=old.open;old.querySelectorAll("details[id]").forEach(d=>{const twin=fresh.querySelector("#"+CSS.escape(d.id));if(twin){twin.open=d.open}});old.querySelectorAll("select[name]").forEach(s=>{const twin=fresh.querySelector('select[name="'+CSS.escape(s.name)+'"]');if(twin&&[...twin.options].some(o=>o.value===s.value)){twin.value=s.value}})};const buttonKey=b=>[b.form?.querySelector('input[name="action"]')?.value??"",b.name,b.value].join("\n");const focusTwin=(el,section)=>{let twin=null;if(el.matches("summary")){const d=el.closest("details");twin=d.id===""||d.id===section.id?null:section.querySelector("#"+CSS.escape(d.id)+" > summary")}else if(el.matches("select[name]")){twin=section.querySelector('select[name="'+CSS.escape(el.name)+'"]')}else if(el.matches("button")){twin=[...section.querySelectorAll("button")].find(b=>!b.disabled&&buttonKey(b)===buttonKey(el))}(twin??section.querySelector(":scope > summary"))?.focus({preventScroll:true})};const follow=()=>{let live=document.getElementById("aa-import-live");if(!live?.dataset.aaProgress||!live.dataset.aaSections){return}const visible=()=>document.visibilityState==="visible";const canonical=json=>{try{return JSON.stringify(JSON.parse(json??""))}catch{return null}};let shown=canonical(live.dataset.aaShown);let delay=POLL_MS;let timer=null;let busy=false;let stopped=false;const schedule=()=>{if(!stopped&&!busy&&timer===null&&visible()){timer=setTimeout(poll,delay)}};const outdated=()=>{stopped=true;live.classList.add("aa-err");live.textContent=live.dataset.aaStale??""};const refresh=async()=>{const res=await fetch(live.dataset.aaSections,{credentials:"same-origin",cache:"no-store"});if(res.status===401||res.status===403){outdated();return false}if(!res.ok){return false}const doc=(new DOMParser).parseFromString(await res.text(),"text/html");if(!doc.querySelector("details[data-aa-live]")){return false}const active=document.activeElement;let skipped=false;document.querySelectorAll("details[data-aa-live]").forEach(old=>{const fresh=doc.getElementById(old.id);if(!fresh?.matches("details[data-aa-live]")){return}const focused=old.contains(active)?active:null;if(focused?.matches("input, textarea")){skipped=true;return}const node=document.adoptNode(fresh);keepState(old,node);old.replaceWith(node);if(focused){focusTwin(focused,node)}});const next=doc.getElementById("aa-import-live");if(next){const node=document.adoptNode(next);live.replaceWith(node);live=node;shown=canonical(live.dataset.aaShown)}else if(!skipped){live.remove();stopped=true}return true};const poll=async()=>{timer=null;if(stopped||busy||!visible()){return}busy=true;let ok=false;try{const res=await fetch(live.dataset.aaProgress,{credentials:"same-origin",cache:"no-store",headers:{Accept:"application/json"}});if(res.status===401||res.status===403){outdated()}else if(res.ok){const progress=await res.json();ok=progress.state==="running"&&JSON.stringify(progress)===shown||await refresh()}}catch{}finally{busy=false}delay=ok?POLL_MS:Math.min(delay*2,MAX_MS);schedule()};document.addEventListener("visibilitychange",schedule);schedule()};if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",follow)}else{follow()}})();